'use client';

import { useEffect, useRef, useState } from 'react';
import { Activity, ArrowRight, ArrowUpRight, BarChart3, BookOpen, Check, CheckCheck, ChevronRight, CircleHelp, ClipboardCheck, Copy, Eye, FileText, Heart, HeartHandshake, Languages, Leaf, LoaderCircle, MessageCircle, Plus, RotateCcw, Settings2, ShieldCheck, Sparkles, ThumbsDown, ThumbsUp, Upload, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { api, connected } from '@/lib/api';
import { newProfile } from '@/lib/mock';
import { hasConflict, isUrgent, redactText, verifiedEvidence } from '@/lib/safety';
import type { AskResult, BarrierResult, CarePlan, DemoCase, EvalResult, ExplainResult, Instruction, PatientProfile, TeachbackResult } from '@/lib/types';
import { Button } from './ui/button';
import { EmptyState, Notice, ReadAloud, SourceQuote, Sources, VoiceInput } from './patient-ui';

type Screen = 'home' | 'setup' | 'documents' | 'plan' | 'understand' | 'teachback' | 'barriers' | 'briefing' | 'learning' | 'evaluation';
const navigation: { id: Screen; en: string; es: string; icon: LucideIcon; needsCase?: boolean }[] = [
  { id: 'home', en: 'Overview', es: 'Inicio', icon: Heart },
  { id: 'setup', en: 'Your preferences', es: 'Tus preferencias', icon: Settings2 },
  { id: 'documents', en: 'Your documents', es: 'Tus documentos', icon: FileText },
  { id: 'plan', en: 'Your care plan', es: 'Tu plan de cuidado', icon: ClipboardCheck, needsCase: true },
  { id: 'understand', en: 'Make it make sense', es: 'Entender tu cuidado', icon: BookOpen, needsCase: true },
  { id: 'teachback', en: 'Check understanding', es: 'Comprobar comprensión', icon: CheckCheck, needsCase: true },
  { id: 'barriers', en: 'Share a concern', es: 'Compartir inquietudes', icon: MessageCircle, needsCase: true },
  { id: 'briefing', en: 'Message your care team', es: 'Mensaje al equipo', icon: HeartHandshake, needsCase: true },
];
const barrierLabels: Record<string, [string, string]> = { side_effect: ['Side effects', 'Efectos secundarios'], cost: ['Cost', 'Costo'], ran_out_refill: ['Refill', 'Recarga'], forgot: ['Remembering', 'Recordar'], schedule_conflict: ['Schedule', 'Horario'], confusion: ['Confusing instructions', 'Instrucciones confusas'], wants_to_stop: ['Wanting to stop', 'Querer suspender'], doesnt_see_importance: ['Why it matters', 'Por qué importa'], uncertain: ['Something else', 'Otra cosa'] };
const appStorage = 'rexo-ui-v1';

export function RexoApp() {
  const [screen, setScreen] = useState<Screen>('home');
  const [profile, setProfile] = useState<PatientProfile>(newProfile());
  const [plan, setPlan] = useState<CarePlan | null>(null);
  const [cases, setCases] = useState<DemoCase[]>([]);
  const [ready, setReady] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [toast, setToast] = useState('');
  const [urgent, setUrgent] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const [avs, setAvs] = useState('');
  const [note, setNote] = useState('');
  const [syntheticConfirmed, setSyntheticConfirmed] = useState(false);
  const [instructionId, setInstructionId] = useState('');
  const [explanation, setExplanation] = useState<ExplainResult | null>(null);
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState<AskResult | null>(null);
  const [response, setResponse] = useState('');
  const [teachback, setTeachback] = useState<TeachbackResult | null>(null);
  const [concern, setConcern] = useState('');
  const [barrier, setBarrier] = useState<BarrierResult | null>(null);
  const [labels, setLabels] = useState<string[]>([]);
  const [includedConcerns, setIncludedConcerns] = useState<string[]>([]);
  const [includedConflicts, setIncludedConflicts] = useState<string[]>([]);
  const [draftEn, setDraftEn] = useState('');
  const [draftPatient, setDraftPatient] = useState('');
  const [draftLanguage, setDraftLanguage] = useState<'en' | 'patient'>('en');
  const [evaluation, setEvaluation] = useState<EvalResult | null>(null);
  const [definedTerm, setDefinedTerm] = useState('');
  const [feedbackGiven, setFeedbackGiven] = useState(false);
  const [concernSaved, setConcernSaved] = useState(false);
  const fileInput = useRef<HTMLInputElement>(null);
  const mainRef = useRef<HTMLElement>(null);
  const resetRef = useRef<HTMLElement>(null);
  const navRef = useRef<HTMLElement>(null);
  const es = profile.language === 'es';
  const t = (en: string, spanish: string) => es ? spanish : en;
  const instruction = plan?.instructions.find(item => item.id === instructionId);
  const context = { case_id: plan?.case_id ?? '', profile_id: profile.profile_id };
  const mode = plan?.mode ?? profile.mode;
  const unresolved = plan?.conflicts.filter(item => !item.resolved) ?? [];

  useEffect(() => {
    let cancelled = false;
    async function initialize() {
      try {
        let saved: { profileId?: string; caseId?: string; taskStatuses?: Record<string, string> } = {};
        try { saved = JSON.parse(sessionStorage.getItem(appStorage) ?? '{}'); } catch { /* Fresh session. */ }
        const [available, person] = await Promise.all([api.demoCases(), saved.profileId ? api.getProfile(saved.profileId) : api.createProfile({ language: 'en', detail: 'brief', modes: ['read'] })]);
        if (cancelled) return;
        setCases(available); setProfile(person);
        if (saved.caseId) {
          try { const carePlan = await api.getCase(saved.caseId); if (!cancelled) { carePlan.tasks = carePlan.tasks.map(task => ({ ...task, status: task.status !== 'needs_clarification' && saved.taskStatuses?.[task.id] === 'patient_reported_done' ? 'patient_reported_done' : task.status })); acceptPlan(carePlan); } }
          catch { if (!cancelled) setToast('Choose a sample to start a new case.'); }
        }
      } catch (cause) { if (!cancelled) setError(cause instanceof Error ? cause.message : 'Could not load the demo.'); }
      finally { if (!cancelled) setReady(true); }
    }
    void initialize();
    return () => { cancelled = true; };
  }, []);
  useEffect(() => {
    if (!ready) return;
    try { sessionStorage.setItem(appStorage, JSON.stringify({ profileId: profile.profile_id, caseId: plan?.case_id, taskStatuses: Object.fromEntries(plan?.tasks.map(item => [item.id, item.status]) ?? []) })); } catch { /* Storage can be disabled. */ }
  }, [ready, profile.profile_id, plan]);
  useEffect(() => { document.documentElement.lang = profile.language; }, [profile.language]);
  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 6500); return () => clearTimeout(timer); }, [toast]);
  useEffect(() => { mainRef.current?.focus({ preventScroll: true }); navRef.current?.querySelector('[aria-current]')?.scrollIntoView({ block: 'nearest', inline: 'center' }); window.scrollTo({ top: 0, behavior: 'instant' }); }, [screen]);
  useEffect(() => {
    if (!resetOpen) return;
    const previousFocus = document.activeElement as HTMLElement | null;
    const dialog = resetRef.current;
    dialog?.querySelector<HTMLButtonElement>('button')?.focus();
    function trap(event: KeyboardEvent) {
      if (event.key === 'Escape' && !busy) { setResetOpen(false); return; }
      if (event.key !== 'Tab') return;
      const buttons = dialog?.querySelectorAll<HTMLButtonElement>('button:not(:disabled)');
      if (!buttons?.length) { event.preventDefault(); return; }
      const first = buttons[0], last = buttons[buttons.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    }
    document.addEventListener('keydown', trap);
    return () => { document.removeEventListener('keydown', trap); previousFocus?.focus(); };
  }, [resetOpen, busy]);

  async function run(action: () => Promise<void>) {
    if (busy) return;
    setBusy(true); setError('');
    try { await action(); } catch (cause) { setError(cause instanceof Error ? cause.message : 'Something went wrong. Please try again.'); }
    finally { setBusy(false); }
  }
  function navigate(next: Screen) { if (urgent || busy) return; setScreen(next); setError(''); setDefinedTerm(''); }
  function acceptPlan(next: CarePlan) {
    setPlan(next); setInstructionId(next.instructions.find(item => item.kind === 'medication')?.id ?? next.instructions[0]?.id ?? '');
    setAvs(next.documents.filter(doc => doc.type === 'after_visit_summary').map(doc => doc.text).join('\n\n'));
    setNote(next.documents.filter(doc => doc.type === 'clinical_note').map(doc => doc.text).join('\n\n'));
    setSyntheticConfirmed(true); setExplanation(null); setAnswer(null); setQuestion(''); setTeachback(null); setResponse(''); setConcern(''); setBarrier(null); setLabels([]); setConcernSaved(false); setDraftEn(''); setDraftPatient(''); setIncludedConcerns([]); setIncludedConflicts(next.conflicts.filter(item => !item.resolved).map(item => item.id));
  }
  async function selectCase(id: string) {
    await run(async () => {
      const next = await api.createCase({ demo_case_id: id });
      const person = await api.updateProfile(profile.profile_id, { concerns: [], teach_back_history: [] });
      acceptPlan(next); setProfile(person); setScreen('setup');
    });
  }
  async function updateProfile(input: Partial<PatientProfile>) { const next = await api.updateProfile(profile.profile_id, input); setProfile(next); return next; }
  function checkUrgent(text: string) { if (isUrgent(text)) { setUrgent(true); return true; } return false; }
  function chooseInstruction(id: string) { setInstructionId(id); setExplanation(null); setTeachback(null); setResponse(''); setFeedbackGiven(false); setDefinedTerm(''); }
  async function explain(style = profile.detail) {
    await run(async () => {
      const result = await api.explain({ ...context, instruction_id: instructionId, style_override: style });
      if (!result.fact_check.passed || !plan || !result.citations.length || result.citations.some(item => !verifiedEvidence(plan, item))) throw new Error(t('This explanation did not pass source verification. Please use the original quotes.', 'La explicación no pasó la verificación. Consulta las citas originales.'));
      setExplanation(result); setFeedbackGiven(false);
    });
  }
  async function readFile(file?: File) {
    if (!file) return;
    await run(async () => {
      if (file.size > 5 * 1024 * 1024) throw new Error('Choose a synthetic file under 5 MB.');
      if (/\.txt$/i.test(file.name) || file.type === 'text/plain') { setAvs(await file.text()); setSyntheticConfirmed(false); setToast(t('Text loaded. Review it before creating a care plan.', 'Texto cargado. Revísalo antes de crear el plan.')); }
      else if (file.type.startsWith('image/')) {
        const result = await api.photo(file);
        if (result.doc_type === 'clinical_note') setNote(result.text); else setAvs(result.text);
        setSyntheticConfirmed(false); setToast(`${result.redacted_count} ${t('identifiers removed. Review the extracted text.', 'identificadores eliminados. Revisa el texto.')}`);
      } else throw new Error(t('Use a .txt file or paste the text from your synthetic PDF. Photo intake requires the backend.', 'Usa un archivo .txt o pega el texto del PDF sintético. Las fotos requieren el backend.'));
    });
    if (fileInput.current) fileInput.current.value = '';
  }
  function toggle<T>(values: T[], value: T) { return values.includes(value) ? values.filter(item => item !== value) : [...values, value]; }
  function stepFooter(next: Screen, label: string) { return <div className="step-footer"><span><ShieldCheck size={16} />{t('Your pace. Your choices.', 'Tu ritmo. Tus decisiones.')}</span><Button onClick={() => navigate(next)} disabled={busy}>{label}<ArrowRight size={17} /></Button></div>; }
  function instructionPicker() { return <label className="field instruction-picker"><span>{t('Choose an instruction', 'Elige una instrucción')}</span><select value={instructionId} onChange={event => chooseInstruction(event.target.value)}>{plan?.instructions.map(item => <option key={item.id} value={item.id}>{item.medication_name ?? item.kind.replace('_', ' ')} · {item.evidence.document_id}{hasConflict(plan, item) ? t(' · needs clarification', ' · necesita aclaración') : ''}</option>)}</select></label>; }

  return <div className="app-shell">
    <a className="skip-link" href="#main-content">{t('Skip to content', 'Ir al contenido')}</a>
    <aside className="sidebar">
      <button className="brand" onClick={() => navigate('home')} aria-label="REXO home"><span className="brand-mark"><Plus size={25} strokeWidth={3} /></span>rexo<span className="brand-dot">.</span></button>
      <div className="sidebar-label">{t('A LITTLE CLARITY, EVERY DAY', 'UN POCO DE CLARIDAD, CADA DÍA')}</div>
      <nav ref={navRef} aria-label={t('Your care journey', 'Tu recorrido de cuidado')}>{navigation.map((item, index) => <button key={item.id} className={`nav-item ${screen === item.id ? 'active' : ''}`} aria-current={screen === item.id ? 'step' : undefined} disabled={busy || urgent || (!!item.needsCase && !plan)} onClick={() => navigate(item.id)}><item.icon size={19} /><span>{es ? item.es : item.en}</span>{screen === item.id && <span className="nav-active-dot" />}{index === 0 && plan && screen !== 'home' && <span className="nav-small-dot" />}</button>)}</nav>
      <div className="sidebar-bottom"><div className="sidebar-card"><span className="small-icon"><Leaf size={18} /></span><strong>{t('Made around you.', 'Hecho para ti.')}</strong><p>{t('A little more understanding. A little more confidence.', 'Más comprensión. Más confianza.')}</p><button onClick={() => navigate('learning')} disabled={urgent || busy}>{t('See what REXO learned', 'Lo que REXO aprendió')}<ArrowUpRight size={15} /></button></div><button className={`utility-link ${screen === 'evaluation' ? 'selected' : ''}`} onClick={() => navigate('evaluation')} disabled={urgent || busy}><BarChart3 size={16} />{t('Behind the demo', 'Sobre la demostración')}</button><button className="utility-link" onClick={() => setResetOpen(true)} disabled={busy}><RotateCcw size={16} />{t('Reset demo', 'Reiniciar demo')}</button></div>
    </aside>
    <div className="workspace">
      <header className="topbar"><div className="breadcrumb">{t('Your care companion', 'Tu compañero de cuidado')}<ChevronRight size={14} /><strong>{screen === 'learning' ? t('What REXO learned', 'Lo que REXO aprendió') : screen === 'evaluation' ? t('Evaluation', 'Evaluación') : navigation.find(item => item.id === screen)?.[es ? 'es' : 'en']}</strong></div><div className="top-actions"><span className={`mode-pill ${mode === 'live' ? 'live' : ''}`}><span />{mode === 'live' ? t('Connected care service', 'Servicio conectado') : 'Demo mode (seeded)'}</span><button className="language-button" disabled={busy || !ready || urgent} onClick={() => run(async () => { await updateProfile({ language: es ? 'en' : 'es' }); setExplanation(null); setAnswer(null); setTeachback(null); setBarrier(null); setDraftEn(''); setDraftPatient(''); })}><Languages size={17} />{es ? 'Español' : 'English'}</button><span className="avatar" aria-hidden="true">A</span></div></header>
      <div className="synthetic-banner"><ShieldCheck size={14} /><span>SYNTHETIC DEMO RECORD — NOT A REAL PATIENT</span></div>
      <nav className="mobile-utilities" aria-label={t('Demo controls', 'Controles de la demo')}><button disabled={urgent || busy} onClick={() => navigate('learning')}><Leaf size={15} />{t('My profile', 'Mi perfil')}</button><button disabled={urgent || busy} onClick={() => navigate('evaluation')}><BarChart3 size={15} />{t('Evaluation', 'Evaluación')}</button><button disabled={busy} onClick={() => setResetOpen(true)}><RotateCcw size={15} />{t('Reset', 'Reiniciar')}</button></nav>
      <main id="main-content" tabIndex={-1} ref={mainRef}>
        {error && <div className="error-banner" role="alert"><CircleHelp size={19} /><span>{error}</span><button aria-label="Dismiss error" onClick={() => setError('')}><X size={16} /></button></div>}
        {busy && <div className="loading-indicator" role="status"><LoaderCircle size={17} className="spin" />{t('Working on it…', 'Un momento…')}</div>}
        {!ready ? <EmptyState title={t('Getting things ready', 'Preparando todo')}>{t('Loading your demo and preferences…', 'Cargando tu demo y preferencias…')}</EmptyState> : urgent ? <section className="urgent-panel" role="alert"><div className="urgent-icon"><Heart size={35} /></div><p className="eyebrow">{t('GET HELP NOW', 'BUSCA AYUDA AHORA')}</p><h1>{t('Call 911 or your care team now.', 'Llama al 911 o a tu equipo médico ahora.')}</h1><p>{t('This demo cannot assess urgent symptoms. The normal flow has been paused.', 'Esta demo no puede evaluar síntomas urgentes. El recorrido se ha pausado.')}</p><Button asChild variant="destructive"><a href="tel:911">{t('Call 911', 'Llamar al 911')}<ArrowUpRight size={18} /></a></Button><p className="helper">{t('For this synthetic demonstration, use Reset demo to start over.', 'Para esta demostración sintética, reinicia la demo para empezar de nuevo.')}</p></section> : <>
        {screen === 'home' && <>
          <div className="welcome-line"><span><span className="sun-dot" />{t('A little support for what comes next', 'Un poco de apoyo para lo que sigue')}</span><span>REXO / {t('PATIENT FIRST', 'EL PACIENTE PRIMERO')}</span></div>
          <section className="hero"><div className="hero-copy"><p className="eyebrow"><span className="tiny-line" />{t('LET’S TAKE IT ONE STEP AT A TIME', 'VAMOS PASO A PASO')}</p><h1>{t('Your care,', 'Tu cuidado,')}<br /><em>{t('understood.', 'más claro.')}</em><br />{t('Your concerns, heard.', 'Tu voz, escuchada.')}</h1><p>{t('Turn the paperwork from your visit into a clearer path forward. Understand your instructions, ask questions, and speak up for what you need.', 'Convierte los documentos de tu visita en un camino más claro. Entiende tus instrucciones, haz preguntas y expresa lo que necesitas.')}</p><Button disabled={!cases.length || busy} onClick={() => plan ? navigate('plan') : selectCase(cases[0].case_id)}>{plan ? t('Continue your care plan', 'Continuar tu plan') : t('Explore a sample care plan', 'Explorar un plan de ejemplo')}<ArrowRight size={18} /></Button><div className="hero-reassurance"><ShieldCheck size={15} />{t('You decide what to share. Always.', 'Tú decides qué compartir. Siempre.')}</div></div>
          <div className="hero-art" aria-hidden="true"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><span className="art-star star-one">✳</span><span className="art-star star-two">✳</span><div className="floating-tag"><span><Check size={13} /></span>{t('A little clearer.', 'Un poco más claro.')}</div><div className="paper-card paper-back"><span /><span /><span /></div><div className="paper-card paper-front"><div className="paper-top"><span className="paper-logo"><Plus size={15} /></span><span>YOUR CARE, SIMPLIFIED</span><span>↗</span></div><h3>{t('One step closer', 'Un paso más cerca')}<br />{t('to feeling sure.', 'de entender.')}</h3><div className="paper-check"><span><Check size={12} /></span>{t('Understand my visit', 'Entender mi visita')}</div><div className="paper-check"><span><Check size={12} /></span>{t('Know what to ask', 'Saber qué preguntar')}</div><div className="paper-check muted"><span /><div>{t('Make my voice heard', 'Expresar mi voz')}</div></div><div className="paper-footer"><Heart size={15} />{t('With you, after the visit.', 'Contigo, después de la visita.')}</div></div><span className="heart-bubble"><Heart size={30} /></span></div></section>
          <div className="section-heading"><div><p className="eyebrow">{t('A SAFE PLACE TO EXPLORE', 'UN ESPACIO PARA EXPLORAR')}</p><h2>{t('Start with a story.', 'Empieza con una historia.')}</h2></div><span className="subtle">{t('Fictional records. Real interactions.', 'Registros ficticios. Interacciones reales.')}</span></div>
          <div className="case-grid">{cases.map((item, index) => <button key={item.case_id} className={`case-card case-${index}`} disabled={busy} onClick={() => selectCase(item.case_id)}><div className="case-top"><span className="case-icon">{index === 0 ? <Eye size={23} /> : index === 1 ? <Activity size={23} /> : <CheckCheck size={23} />}</span><span className="case-number">0{index + 1}<ArrowUpRight size={19} /></span></div><span className="case-category">{index === 0 ? t('AFTER A PROCEDURE', 'DESPUÉS DE UN PROCEDIMIENTO') : index === 1 ? t('EVERYDAY CARE', 'CUIDADO DIARIO') : t('COMPARE & UNDERSTAND', 'COMPARAR Y ENTENDER')}</span><h3>{es ? ['Después de una cirugía ocular', 'Controlar la presión arterial', 'Documentos que coinciden'][index] ?? item.title : item.title}</h3><p>{es ? ['Dos documentos. Una pregunta sobre las gotas.', 'Revisa instrucciones que no coinciden.', 'Explora un plan con instrucciones consistentes.'][index] ?? item.description : item.description}</p><span className="case-link">{t('Open sample', 'Abrir ejemplo')}<ArrowRight size={16} /></span></button>)}</div>
          <section className="how-strip"><div><span>01</span><FileText size={21} /><div><strong>{t('Bring it together', 'Reúne tus documentos')}</strong><p>{t('Your documents, in one place.', 'Tus documentos, en un solo lugar.')}</p></div></div><ArrowRight className="strip-arrow" size={18} /><div><span>02</span><BookOpen size={21} /><div><strong>{t('Find your clarity', 'Encuentra claridad')}</strong><p>{t('Understand, at your own pace.', 'Entiende a tu propio ritmo.')}</p></div></div><ArrowRight className="strip-arrow" size={18} /><div><span>03</span><MessageCircle size={21} /><div><strong>{t('Make yourself heard', 'Hazte escuchar')}</strong><p>{t('Put your concerns into words.', 'Expresa tus inquietudes.')}</p></div></div></section>
        </>}

        {screen === 'setup' && <><PageHeading step="01" title={t('Care that speaks your language.', 'Cuidado que habla tu idioma.')} subtitle={t('Tell us what works for you. You can change these choices anytime.', 'Dinos qué te funciona. Puedes cambiar estas opciones en cualquier momento.')} /><section className="panel setup-panel"><div className="setup-row"><div><h3>{t('Which language feels right?', '¿Qué idioma prefieres?')}</h3><p>{t('Original source quotes stay in their original language.', 'Las citas originales conservan su idioma.')}</p></div><div className="segmented">{(['en', 'es'] as const).map(language => <button key={language} aria-pressed={profile.language === language} disabled={busy} onClick={() => run(async () => { await updateProfile({ language }); setExplanation(null); })}>{language === 'en' ? 'English' : 'Español'}{profile.language === language && <Check size={15} />}</button>)}</div></div><div className="setup-row"><div><h3>{t('How much detail?', '¿Cuántos detalles?')}</h3><p>{t('The same facts, explained your way.', 'Los mismos datos, explicados a tu manera.')}</p></div><div className="segmented">{(['brief', 'detailed'] as const).map(detail => <button key={detail} aria-pressed={profile.detail === detail} disabled={busy} onClick={() => run(async () => { await updateProfile({ detail }); setExplanation(null); })}>{detail === 'brief' ? t('Keep it brief', 'Breve') : t('More detail', 'Más detalles')}{profile.detail === detail && <Check size={15} />}</button>)}</div></div><div className="setup-row"><div><h3>{t('How do you like to learn?', '¿Cómo te gusta aprender?')}</h3><p>{t('Choose any that help you.', 'Elige las opciones que te ayuden.')}</p></div><div className="chips">{(['read', 'listen', 'visual'] as const).map(value => <button key={value} className="chip" aria-pressed={profile.modes.includes(value)} disabled={busy || (profile.modes.length === 1 && profile.modes.includes(value))} onClick={() => run(async () => { await updateProfile({ modes: toggle(profile.modes, value) }); })}>{value === 'read' ? t('Read', 'Leer') : value === 'listen' ? t('Listen', 'Escuchar') : t('Visual', 'Visual')}{profile.modes.includes(value) && <Check size={14} />}</button>)}</div></div><label className="field"><span>{t('Anything about your day you want us to know?', '¿Algo de tu día que quieras compartir?')} <small>{t('Optional', 'Opcional')}</small></span><textarea rows={2} maxLength={500} value={profile.context_opt_in} placeholder={t('For example, I work rotating shifts.', 'Por ejemplo, trabajo en turnos rotativos.')} onChange={event => setProfile({ ...profile, context_opt_in: event.target.value })} /><span className="helper">{t('Only used for context you choose to share. Never to infer your ability.', 'Solo usamos el contexto que tú compartes. Nunca para inferir tu capacidad.')}</span></label></section><div className="step-footer"><span><ShieldCheck size={16} />{t('Your preferences stay in your control.', 'Tú controlas tus preferencias.')}</span><Button disabled={busy} onClick={() => run(async () => { await updateProfile({ context_opt_in: profile.context_opt_in }); setScreen('documents'); })}>{t('Save & continue', 'Guardar y continuar')}<ArrowRight size={17} /></Button></div></>}

        {screen === 'documents' && <><PageHeading step="02" title={t('Let’s bring it all together.', 'Reunamos todo.')} subtitle={t('Compare your after-visit summary with the clinical note. Use synthetic text only.', 'Compara el resumen de visita con la nota clínica. Usa solo texto sintético.')} /><div className="document-toolbar"><label className="field"><span>{t('Load a sample', 'Cargar ejemplo')}</span><select value="" disabled={busy} onChange={event => run(async () => { const next = await api.createCase({ demo_case_id: event.target.value }); acceptPlan(next); await updateProfile({ concerns: [], teach_back_history: [] }); })}><option value="" disabled>{t('Choose a sample pair', 'Elige un par de ejemplo')}</option>{cases.map(item => <option key={item.case_id} value={item.case_id}>{item.title}</option>)}</select></label><input className="sr-only" ref={fileInput} type="file" accept=".txt,image/*" aria-label="Upload synthetic document" onChange={event => readFile(event.target.files?.[0])} /><Button variant="secondary" disabled={busy} onClick={() => fileInput.current?.click()}><Upload size={17} />{t('Upload synthetic text / photo', 'Subir texto / foto sintéticos')}</Button></div><div className="two-column"><section className="panel"><div className="panel-heading"><span className="small-icon lavender"><FileText size={20} /></span><div><h3>{t('After-visit summary', 'Resumen de visita')}</h3><p>{t('The instructions you took home', 'Las instrucciones para casa')}</p></div></div><label className="field"><span className="sr-only">{t('After-visit summary text', 'Texto del resumen de visita')}</span><textarea className="document-text" rows={12} value={avs} maxLength={30000} onChange={event => { setAvs(event.target.value); setSyntheticConfirmed(false); }} placeholder={t('Paste synthetic after-visit text…', 'Pega el resumen sintético…')} /></label></section><section className="panel"><div className="panel-heading"><span className="small-icon peach"><FileText size={20} /></span><div><h3>{t('Clinical note', 'Nota clínica')}</h3><p>{t('The note from your care team', 'La nota de tu equipo médico')}</p></div></div><label className="field"><span className="sr-only">{t('Clinical note text', 'Texto de la nota clínica')}</span><textarea className="document-text" rows={12} value={note} maxLength={30000} onChange={event => { setNote(event.target.value); setSyntheticConfirmed(false); }} placeholder={t('Paste the synthetic clinical note…', 'Pega la nota clínica sintética…')} /></label></section></div><div className="document-preview"><span><ShieldCheck size={16} />{redactText(avs).count + redactText(note).count} {t('identifier lines will be removed', 'líneas identificadoras se eliminarán')}</span><details><summary>{t('Preview cleaned text', 'Ver texto limpio')}</summary><pre>{redactText(avs).text}{'\n\n'}{redactText(note).text}</pre></details></div>{!connected && <Notice>{t('Seeded mode recognizes the sample medicines, follow-up lines, and warnings. Other text may produce no instructions. Full extraction and photo intake require the backend. For PDFs, paste the extracted text.', 'El modo demo reconoce los medicamentos, citas y advertencias de ejemplo. Otro texto puede no generar instrucciones. La extracción completa y fotos requieren el backend. Para PDF, pega el texto.')}</Notice>}<label className="checkbox-line"><input type="checkbox" checked={syntheticConfirmed} onChange={event => setSyntheticConfirmed(event.target.checked)} />{t('I confirm these are fictional documents with no real patient information.', 'Confirmo que son documentos ficticios sin información real de pacientes.')}</label><div className="step-footer"><span>{t('Every extracted instruction links back to its source.', 'Cada instrucción extraída enlaza con su fuente.')}</span><Button disabled={busy || !syntheticConfirmed || !(avs.trim() || note.trim())} onClick={() => run(async () => { const next = await api.createCase({ documents: [{ text: avs, type_hint: 'after_visit_summary' }, { text: note, type_hint: 'clinical_note' }].filter(doc => doc.text.trim()) as { text: string; type_hint: 'after_visit_summary' | 'clinical_note' }[] }); acceptPlan(next); await updateProfile({ concerns: [], teach_back_history: [] }); setScreen('plan'); })}>{t('Create my care plan', 'Crear mi plan')}<ArrowRight size={17} /></Button></div></>}

        {screen === 'plan' && plan && <><PageHeading step="03" title={t('A clearer picture of your care.', 'Una visión más clara de tu cuidado.')} subtitle={t('Everything here comes from your documents. Tap a source to see the exact words.', 'Todo proviene de tus documentos. Abre una fuente para ver las palabras exactas.')} /><div className="stats-row"><div><FileText size={19} /><strong>{plan.documents.length}</strong><span>{t('documents together', 'documentos reunidos')}</span></div><div><ClipboardCheck size={19} /><strong>{plan.instructions.length}</strong><span>{t('source-linked instructions', 'instrucciones con fuente')}</span></div><div className={unresolved.length ? 'stat-warning' : ''}><CircleHelp size={19} /><strong>{unresolved.length}</strong><span>{t('questions to clarify', 'preguntas por aclarar')}</span></div></div>{unresolved.map(conflict => <section className="conflict-card" key={conflict.id}><div className="conflict-heading"><span className="small-icon"><CircleHelp size={22} /></span><div><p className="eyebrow">{t('NEEDS CLARIFICATION', 'NECESITA ACLARACIÓN')}</p><h3>{conflict.type === 'frequency_mismatch' ? t('Different instructions for how often.', 'Instrucciones diferentes sobre la frecuencia.') : conflict.type === 'dose_mismatch' ? t('The doses don’t match.', 'Las dosis no coinciden.') : conflict.type === 'action_mismatch' ? t('One document says continue. Another says avoid.', 'Un documento dice continuar. Otro dice evitar.') : t('Your documents give different instructions.', 'Tus documentos dan instrucciones diferentes.')}</h3></div></div><div className="two-column">{conflict.instruction_ids.map(id => { const item = plan.instructions.find(item => item.id === id); return item && <SourceQuote key={id} evidence={item.evidence} plan={plan} expanded />; })}</div><p>{t('Your care team needs to clarify this. REXO will not choose an instruction or recommend a schedule.', 'Tu equipo médico debe aclararlo. REXO no elige una instrucción ni recomienda un horario.')}</p><button className="text-link" onClick={() => { setIncludedConflicts(previous => [...new Set([...previous, conflict.id])]); setDraftEn(''); setDraftPatient(''); navigate('briefing'); }}>{t('Bring this to my care team', 'Preguntar a mi equipo')}<ArrowRight size={16} /></button></section>)}{!plan.instructions.length && <EmptyState title={t('No supported instructions found', 'No se encontraron instrucciones compatibles')}>{t('Your text has not been replaced with a sample. Try a sample pair or connect the extraction backend.', 'Tu texto no fue reemplazado con un ejemplo. Prueba un par de ejemplo o conecta el backend.')}</EmptyState>}{!unresolved.length && plan.instructions.length > 0 && <Notice tone="success">{t('No conflicts were found in the extracted instructions. This does not verify the clinical correctness of your documents.', 'No se encontraron conflictos en las instrucciones extraídas. Esto no verifica la exactitud clínica de los documentos.')}</Notice>}<div className="section-heading"><h2>{t('Your instructions, with context.', 'Tus instrucciones, con contexto.')}</h2><span className="subtle">{t('Missing details stay unknown.', 'Los datos ausentes quedan desconocidos.')}</span></div><div className="instruction-grid">{plan.instructions.map(item => <section className={`panel instruction-card ${item.kind === 'warning_sign' ? 'warning-card' : ''}`} key={item.id}><div className="instruction-label"><span>{item.kind === 'medication' ? t('MEDICATION', 'MEDICAMENTO') : item.kind === 'warning_sign' ? t('WARNING SIGN', 'SEÑAL DE ALERTA') : t('FOLLOW-UP', 'SEGUIMIENTO')}</span>{hasConflict(plan, item) && <span className="status-badge warning">{t('Needs clarification', 'Por aclarar')}</span>}</div><h3>{item.medication_name ?? (item.kind === 'warning_sign' ? t('When to contact your care team', 'Cuándo contactar al equipo') : t('Your next visit', 'Tu próxima visita'))}</h3><dl className="fact-grid">{item.kind === 'medication' ? <><div><dt>{t('Dose', 'Dosis')}</dt><dd>{item.dose ?? t('Unknown', 'Desconocida')}</dd></div><div><dt>{t('Frequency / day', 'Frecuencia / día')}</dt><dd>{item.frequency_per_day ?? t('Unknown', 'Desconocida')}</dd></div><div><dt>{t('Duration', 'Duración')}</dt><dd>{item.duration ?? t('Unknown', 'Desconocida')}</dd></div><div><dt>{t('Refills', 'Recargas')}</dt><dd>{item.refills ?? t('Unknown', 'Desconocidas')}</dd></div></> : item.due ? <div><dt>{t('Documented date', 'Fecha documentada')}</dt><dd>{item.due}</dd></div> : null}</dl><SourceQuote evidence={item.evidence} plan={plan} expanded={item.kind === 'warning_sign'} /><button className="text-link" onClick={() => { chooseInstruction(item.id); navigate('understand'); }}>{t('Help me understand', 'Ayúdame a entender')}<ArrowRight size={15} /></button></section>)}</div>{plan.tasks.length > 0 && <section className="panel checklist-panel"><h3>{t('Your personal checklist', 'Tu lista personal')}</h3><p className="helper">{t('Checked means reported by you, saved in this browser session. Conflicting instructions stay locked for clarification.', 'Marcado significa reportado por ti, guardado en esta sesión. Las instrucciones en conflicto requieren aclaración.')}</p>{plan.tasks.map(task => { const related = plan.instructions.find(item => item.id === task.instruction_id); const locked = related ? hasConflict(plan, related) : true; return <div className="checklist-item" key={task.id}><label><input type="checkbox" disabled={locked} checked={task.status === 'patient_reported_done'} onChange={event => setPlan({ ...plan, tasks: plan.tasks.map(item => item.id === task.id ? { ...item, status: event.target.checked ? 'patient_reported_done' : 'open' } : item) })} /><span>{task.label}</span></label><span className={`status-badge ${locked ? 'warning' : ''}`}>{locked ? t('Needs clarification', 'Por aclarar') : task.status === 'patient_reported_done' ? t('Patient-reported done', 'Reportado como hecho') : t('Open', 'Pendiente')}</span></div>; })}</section>}{stepFooter('understand', t('Make it make sense', 'Entender mi cuidado'))}</>}

        {screen === 'understand' && plan && <><PageHeading step="04" title={t('Let’s make it make sense.', 'Hagamos que tenga sentido.')} subtitle={t('A little less jargon. A little more understanding. The facts stay the same.', 'Menos jerga. Más comprensión. Los datos se mantienen iguales.')} />{instructionPicker()}{instruction && <><div className="two-column explain-columns"><section className="panel"><p className="eyebrow">{t('WHAT YOUR DOCUMENT SAYS', 'LO QUE DICE TU DOCUMENTO')}</p><h3>{instruction.medication_name ?? instruction.kind.replace('_', ' ')}</h3><SourceQuote evidence={instruction.evidence} plan={plan} expanded />{hasConflict(plan, instruction) && <Notice tone="warning">{t('This instruction is part of an unresolved conflict. Both versions remain visible in your care plan.', 'Esta instrucción tiene un conflicto pendiente. Ambas versiones están en tu plan.')}</Notice>}</section><section className="panel explanation-panel"><div className="panel-heading"><Sparkles size={19} /><p className="eyebrow">{t('IN PLAIN LANGUAGE', 'EN PALABRAS SENCILLAS')}</p></div><div className="segmented">{(['brief', 'detailed'] as const).map(style => <button key={style} disabled={busy} aria-pressed={profile.detail === style} onClick={() => run(async () => { const result = await api.feedback({ profile_id: profile.profile_id, kind: 'style_change', payload: { style } }); setProfile(result.profile); setExplanation(null); setFeedbackGiven(false); })}>{style === 'brief' ? t('Brief', 'Breve') : t('Detailed', 'Detallado')}</button>)}</div>{explanation ? <><p className="explanation-text">{explanation.text}</p><p className="helper">{explanation.why_this_style}</p><Sources citations={explanation.citations} plan={plan} /><div className="term-chips">{explanation.defined_terms.map(term => { const name = typeof term === 'string' ? term : term.term; return <button className="term-chip" key={name} disabled={busy} onClick={() => run(async () => { const result = await api.feedback({ profile_id: profile.profile_id, kind: 'term_tap', payload: { term: name } }); setProfile(result.profile); setDefinedTerm(typeof term === 'string' ? t('The backend did not supply a definition for this term.', 'El backend no proporcionó una definición.') : term.definition); })}><CircleHelp size={14} />{name}</button>; })}</div>{definedTerm && <Notice>{definedTerm}</Notice>}<ReadAloud text={explanation.text} language={profile.language} /><div className="feedback-row"><span>{feedbackGiven ? t('Feedback saved', 'Opinión guardada') : t('Did this help?', '¿Te ayudó?')}</span>{[true, false].map(helpful => <Button key={String(helpful)} variant="ghost" size="icon" aria-label={helpful ? t('Helpful', 'Útil') : t('Not helpful', 'No fue útil')} disabled={busy || feedbackGiven} onClick={() => run(async () => { const result = await api.feedback({ profile_id: profile.profile_id, kind: 'thumbs', payload: { style: explanation.style, up: helpful } }); setProfile(result.profile); setFeedbackGiven(true); })}>{helpful ? <ThumbsUp size={17} /> : <ThumbsDown size={17} />}</Button>)}</div></> : <><p>{t('Choose your preferred level of detail, then open the explanation.', 'Elige cuánto detalle prefieres y abre la explicación.')}</p><Button disabled={busy} onClick={() => explain()}>{t('Explain this instruction', 'Explicar esta instrucción')}<Sparkles size={16} /></Button></>}</section></div>{profile.modes.includes('visual') && <div className="visual-path"><span><FileText size={20} />{t('Read the source', 'Leer la fuente')}</span><ArrowRight size={18} /><span><CircleHelp size={20} />{t('Notice a question', 'Identificar una pregunta')}</span><ArrowRight size={18} /><span><HeartHandshake size={20} />{t('Ask your care team', 'Preguntar al equipo')}</span></div>}<section className="panel question-panel"><h3>{t('Something still on your mind?', '¿Todavía tienes una pregunta?')}</h3><form onSubmit={event => { event.preventDefault(); if (checkUrgent(question)) return; void run(async () => { const result = await api.ask({ ...context, question }); if (result.urgent) { setUrgent(true); return; } if (result.citations.some(item => !verifiedEvidence(plan, item)) || (result.in_documents && !result.citations.length)) throw new Error('The answer could not be verified against your documents.'); setAnswer(result); }); }}><label className="field"><span>{t('Ask about your documents', 'Pregunta sobre tus documentos')}</span><textarea rows={2} maxLength={3000} value={question} onChange={event => { setQuestion(event.target.value); setAnswer(null); }} placeholder={t('What do my documents say about…?', '¿Qué dicen mis documentos sobre…?')} /></label><div className="form-actions"><VoiceInput language={profile.language} disabled={busy} onText={text => { if (!checkUrgent(text)) setQuestion(text); }} /><Button type="submit" disabled={busy || !question.trim()}>{t('Ask a question', 'Hacer una pregunta')}<ArrowUpRight size={16} /></Button></div></form>{answer && <div className="result-panel"><p>{answer.answer}</p><Sources citations={answer.citations} plan={plan} /><Button variant="secondary" onClick={() => { setConcern(question); setBarrier(null); setConcernSaved(false); navigate('barriers'); }}>{t('Bring this to my care team', 'Preguntar a mi equipo')}</Button></div>}</section></>}{stepFooter('teachback', t('Check my understanding', 'Comprobar mi comprensión'))}</>}

        {screen === 'teachback' && plan && <><PageHeading step="05" title={t('In your own words.', 'Con tus propias palabras.')} subtitle={t('This is a chance to spot unclear instructions. You are not being graded.', 'Es una oportunidad para detectar instrucciones poco claras. No es un examen.')} />{instructionPicker()}{instruction && <div className="two-column"><section className="panel"><p className="eyebrow">{t('YOUR SOURCE', 'TU FUENTE')}</p><SourceQuote evidence={instruction.evidence} plan={plan} expanded />{hasConflict(plan, instruction) && <Notice tone="warning">{t('These documents disagree. We will ask for clarification instead of confirming either version.', 'Los documentos no coinciden. Pediremos aclaración en vez de confirmar una versión.')}</Notice>}<p className="helper">{t('For a numerical check without a conflict, explore “A matching pair.”', 'Para comprobar números sin un conflicto, explora “Documentos que coinciden”.')}</p></section><section className="panel"><form onSubmit={event => { event.preventDefault(); if (checkUrgent(response)) return; void run(async () => { const result = await api.teachback({ ...context, instruction_id: instruction.id, response_text: response }); setTeachback(result); setProfile(await api.getProfile(profile.profile_id)); }); }}><label className="field"><span>{t('How would you explain this instruction?', '¿Cómo explicarías esta instrucción?')}</span><textarea rows={5} maxLength={3000} value={response} onChange={event => { setResponse(event.target.value); setTeachback(null); }} placeholder={t('I understand that my document says…', 'Entiendo que mi documento dice…')} /></label><div className="form-actions"><VoiceInput language={profile.language} disabled={busy} onText={text => { if (!checkUrgent(text)) { setResponse(text); setTeachback(null); } }} /><Button type="submit" disabled={busy || !response.trim()}>{t('Check my answer', 'Comprobar respuesta')}<ArrowRight size={16} /></Button></div></form>{teachback && <div className="result-panel" aria-live="polite"><div className="chips">{teachback.labels.map(label => <span className="status-badge" key={label}>{label.replaceAll('_', ' ')}</span>)}</div><p>{teachback.feedback_text}</p><div className="slot-grid">{Object.entries(teachback.slot_check).map(([key, value]) => <div key={key}><span>{key}</span><strong>{value === null ? t('Not checked', 'Sin comprobar') : value === true ? t('Matches quote', 'Coincide') : value === false ? t('Differs', 'Difiere') : value === 'documents_disagree' ? t('Documents disagree', 'Los documentos no coinciden') : String(value)}</strong></div>)}</div><p className="helper">{t('Checked by', 'Comprobado por')}: {teachback.pathway === 'rules' ? t('rules', 'reglas') : teachback.pathway === 'both' ? 'ML + rules' : 'ML'}{teachback.pathway !== 'rules' ? ` · ${t('model confidence', 'confianza del modelo')}: ${Math.round(teachback.confidence * 100)}%` : t(' · No ML confidence is claimed.', ' · No se afirma confianza de ML.')}</p><SourceQuote evidence={instruction.evidence} plan={plan} expanded /></div>}</section></div>}{stepFooter('barriers', t('Share what’s getting in the way', 'Compartir mis inquietudes'))}</>}

        {screen === 'barriers' && plan && <><PageHeading step="06" title={t('What’s getting in the way?', '¿Qué se está interponiendo?')} subtitle={t('The practical things matter, too. Let’s put your concern into words.', 'Las cosas prácticas también importan. Pongamos tu inquietud en palabras.')} /><section className="panel concern-panel"><div className="chips">{Object.entries(barrierLabels).filter(([key]) => !['wants_to_stop', 'doesnt_see_importance'].includes(key)).map(([key, label]) => <button className="chip" key={key} disabled={busy} onClick={() => { const prompts: Record<string, [string, string]> = { side_effect: ['These drops make my eye feel gritty. I’m thinking of stopping.', 'Estas gotas me causan una sensación arenosa. Estoy pensando en dejar de usarlas.'], cost: ['I am worried about the cost.', 'Me preocupa el costo.'], ran_out_refill: ['I ran out and need a refill.', 'Se acabó y necesito una recarga.'], forgot: ['I forgot to take my medicine.', 'Olvidé tomar mi medicamento.'], schedule_conflict: ['My work schedule makes this difficult.', 'Mi horario de trabajo lo hace difícil.'], confusion: ['I am confused by the instructions.', 'Las instrucciones me confunden.'], uncertain: ['', ''] }; setConcern(prompts[key][es ? 1 : 0]); setBarrier(null); setConcernSaved(false); }}>{label[es ? 1 : 0]}</button>)}</div><form onSubmit={event => { event.preventDefault(); if (checkUrgent(concern)) return; void run(async () => { const result = await api.barrier({ ...context, text: concern }); if (result.urgent) { setUrgent(true); return; } setBarrier(result); setLabels(result.labels); setConcernSaved(false); }); }}><label className="field"><span>{t('Tell us what’s on your mind', 'Cuéntanos qué te preocupa')}</span><textarea rows={5} maxLength={3000} value={concern} onChange={event => { setConcern(event.target.value); setBarrier(null); setConcernSaved(false); }} placeholder={t('I’m finding it hard because…', 'Me cuesta porque…')} /></label><div className="form-actions"><VoiceInput language={profile.language} disabled={busy} onText={text => { if (!checkUrgent(text)) { setConcern(text); setBarrier(null); setConcernSaved(false); } }} /><Button disabled={busy || !concern.trim()} type="submit">{t('Help me put it into words', 'Ayúdame a expresarlo')}<ArrowRight size={16} /></Button></div></form>{barrier && <div className="result-panel"><p>{barrier.support_text}</p><h3>{barrier.confirm_prompt}</h3><div className="chips">{Object.entries(barrierLabels).map(([key, label]) => <button className="chip" key={key} aria-pressed={labels.includes(key)} disabled={concernSaved} onClick={() => setLabels(toggle(labels, key))}>{label[es ? 1 : 0]}{labels.includes(key) && <Check size={14} />}</button>)}</div><Button variant="secondary" disabled={busy || !labels.length || concernSaved} onClick={() => run(async () => { const changed = [...labels].sort().join() !== [...barrier.labels].sort().join(); const result = await api.feedback({ profile_id: profile.profile_id, kind: changed ? 'label_correct' : 'label_confirm', payload: { example_id: barrier.example_id, text: concern, labels } }); setProfile(result.profile); setIncludedConcerns(previous => [...new Set([...previous, concern])]); setConcernSaved(true); setDraftEn(''); setDraftPatient(''); setToast(result.model_updated ? t('Concern saved. The classifier was updated.', 'Inquietud guardada. Clasificador actualizado.') : t('Concern saved. No classifier was trained in seeded mode.', 'Inquietud guardada. No se entrenó un clasificador en el modo demo.')); })}>{concernSaved ? <Check size={16} /> : <Plus size={16} />}{concernSaved ? t('Saved to my concern log', 'Guardado en mis inquietudes') : t('Confirm & save my concern', 'Confirmar y guardar')}</Button></div>}</section>{stepFooter('briefing', t('Prepare a message', 'Preparar un mensaje'))}</>}

        {screen === 'briefing' && plan && <><PageHeading step="07" title={t('Your voice. Your message.', 'Tu voz. Tu mensaje.')} subtitle={t('Choose what to include, make it your own, then copy it to share with your care team.', 'Elige qué incluir, personalízalo y cópialo para compartirlo con tu equipo.')} /><div className="briefing-layout"><section className="panel"><h3>{t('What would you like to share?', '¿Qué te gustaría compartir?')}</h3><p className="eyebrow">{t('YOUR CONCERNS', 'TUS INQUIETUDES')}</p>{!profile.concerns.length && <p className="helper">{t('No saved concerns yet. You can still ask about conflicting instructions.', 'Aún no hay inquietudes guardadas. Puedes preguntar sobre conflictos.')}</p>}{profile.concerns.map((item, index) => <label key={index} className="checkbox-line"><input type="checkbox" checked={includedConcerns.includes(item)} onChange={() => { setIncludedConcerns(toggle(includedConcerns, item)); setDraftEn(''); setDraftPatient(''); }} /><span>{item}</span></label>)}<p className="eyebrow">{t('QUESTIONS TO CLARIFY', 'PREGUNTAS POR ACLARAR')}</p>{!unresolved.length && <p className="helper">{t('No unresolved conflicts.', 'Sin conflictos pendientes.')}</p>}{unresolved.map(item => <label key={item.id} className="checkbox-line"><input type="checkbox" checked={includedConflicts.includes(item.id)} onChange={() => { setIncludedConflicts(toggle(includedConflicts, item.id)); setDraftEn(''); setDraftPatient(''); }} /><span>{item.type.replaceAll('_', ' ')} · {plan.instructions.find(instruction => instruction.id === item.instruction_ids[0])?.medication_name ?? t('Follow-up', 'Seguimiento')}</span></label>)}<Button disabled={busy} onClick={() => run(async () => { const result = await api.briefing({ ...context, include: { concerns: includedConcerns, conflicts: includedConflicts } }); if (result.citations.some(item => !verifiedEvidence(plan, item))) throw new Error('The message contains an unverified source. Please try again.'); setDraftEn(result.draft_en); setDraftPatient(result.draft_patient_language); })}><Sparkles size={17} />{draftEn ? t('Regenerate draft', 'Regenerar borrador') : t('Create my draft', 'Crear borrador')}</Button><p className="helper">{t('Nothing is sent by REXO. You decide whether and where to share it.', 'REXO no envía nada. Tú decides si lo compartes y dónde.')}</p></section><section className="panel draft-panel"><div className="panel-heading"><h3>{t('Message preview', 'Vista previa del mensaje')}</h3><span className="status-badge">{t('EDITABLE DRAFT', 'BORRADOR EDITABLE')}</span></div>{es && <div className="segmented"><button aria-pressed={draftLanguage === 'en'} onClick={() => setDraftLanguage('en')}>English</button><button aria-pressed={draftLanguage === 'patient'} onClick={() => setDraftLanguage('patient')}>Español</button></div>}{draftEn ? <><label className="field"><span className="sr-only">{t('Edit your message', 'Edita tu mensaje')}</span><textarea rows={16} value={draftLanguage === 'en' ? draftEn : draftPatient} onChange={event => draftLanguage === 'en' ? setDraftEn(event.target.value) : setDraftPatient(event.target.value)} /></label>{es && <p className="helper">{t('Edits apply to the selected language only. Original quotes and your own words are preserved.', 'Los cambios aplican solo al idioma elegido. Se conservan las citas y tus propias palabras.')}</p>}<div className="form-actions"><span className="helper"><ShieldCheck size={14} />{t('You’re in control.', 'Tú tienes el control.')}</span><Button onClick={() => run(async () => { try { await navigator.clipboard.writeText(draftLanguage === 'en' ? draftEn : draftPatient); setToast(t('Message copied. Share it when you’re ready.', 'Mensaje copiado. Compártelo cuando quieras.')); } catch { throw new Error(t('Clipboard access is unavailable. Select the draft text and copy it manually.', 'No se pudo usar el portapapeles. Selecciona el texto y cópialo manualmente.')); } })}><Copy size={17} />{t('Copy message', 'Copiar mensaje')}</Button></div></> : <EmptyState title={t('A starting point for your conversation.', 'Un inicio para tu conversación.')}>{t('Select what matters to you and create your draft.', 'Selecciona lo que te importa y crea tu borrador.')}</EmptyState>}</section></div>{stepFooter('learning', t('See what REXO learned', 'Ver lo que REXO aprendió'))}</>}

        {screen === 'learning' && <><PageHeading title={t('A little more you, every time.', 'Un poco más a tu medida.')} subtitle={t('Your preferences and your words are yours to view, change, or reset.', 'Tus preferencias y palabras son tuyas: puedes verlas, cambiarlas o borrarlas.')} /><div className="two-column"><section className="panel"><div className="panel-heading"><h3>{t('Your preferences', 'Tus preferencias')}</h3><Button variant="ghost" onClick={() => navigate('setup')}>{t('Edit', 'Editar')}<ArrowUpRight size={15} /></Button></div><dl className="profile-facts"><div><dt>{t('Language', 'Idioma')}</dt><dd>{es ? 'Español' : 'English'}</dd></div><div><dt>{t('Detail', 'Detalle')}</dt><dd>{profile.detail}</dd></div><div><dt>{t('Ways to learn', 'Formas de aprender')}</dt><dd>{profile.modes.join(', ')}</dd></div><div><dt>{t('Context you shared', 'Contexto compartido')}</dt><dd>{profile.context_opt_in || t('Not provided', 'No proporcionado')}</dd></div><div><dt>{t('Teach-back attempts', 'Intentos de comprensión')}</dt><dd>{profile.teach_back_history.length}</dd></div></dl></section><section className="panel"><h3>{t('Words we’re learning together', 'Palabras que aprendemos juntos')}</h3><p className="helper">{t('0 means confusing; 1 means familiar. Adjust any score yourself.', '0 significa confuso; 1 significa familiar. Ajusta cualquier valor.')}</p>{!Object.keys(profile.term_scores).length && <p>{t('Tap a term in an explanation to begin.', 'Toca un término en una explicación para empezar.')}</p>}{Object.entries(profile.term_scores).map(([term, score]) => <label className="term-score" key={term}><span>{term}<strong>{Number(score).toFixed(1)}</strong></span><input aria-label={term} type="range" min="0" max="1" step="0.1" value={score} onChange={event => setProfile(previous => ({ ...previous, term_scores: { ...previous.term_scores, [term]: Number(event.target.value) } }))} /></label>)}{Object.keys(profile.term_scores).length > 0 && <Button variant="secondary" disabled={busy} onClick={() => run(async () => { await updateProfile({ term_scores: profile.term_scores }); setToast(t('Term preferences saved.', 'Preferencias guardadas.')); })}>{t('Save term preferences', 'Guardar preferencias')}</Button>}</section></div><section className="panel"><h3>{t('How your feedback shapes presentation', 'Cómo tus opiniones cambian la presentación')}</h3><p className="helper">{mode === 'demo' ? t('Seeded mode records preference signals. Adaptive selection and classifier training require the backend. These are counters, not measured success rates.', 'El modo demo guarda señales de preferencia. La selección adaptativa y el entrenamiento requieren el backend. Son contadores, no tasas de éxito.') : t('Raw preference model state from your profile. These values are not clinical outcomes.', 'Estado del modelo de preferencias. Estos valores no son resultados clínicos.')}</p><div className="bandit-grid">{Object.entries(profile.style_bandit).map(([style, values]) => <div key={style}><strong>{style}</strong><div className="bandit-bar"><span style={{ width: `${100 * values[0] / (values[0] + values[1])}%` }} /></div><small>α {values[0].toFixed(1)} · β {values[1].toFixed(1)}</small></div>)}</div></section><section className="panel"><h3>{t('Your concern log', 'Tu registro de inquietudes')}</h3>{!profile.concerns.length && <p>{t('No concerns saved yet.', 'Aún no hay inquietudes guardadas.')}</p>}{profile.concerns.map((item, index) => <div className="concern-log-row" key={index}><label className="field"><span className="sr-only">{t('Edit concern', 'Editar inquietud')} {index + 1}</span><textarea rows={2} value={item} maxLength={3000} onChange={event => setProfile(previous => ({ ...previous, concerns: previous.concerns.map((value, i) => i === index ? event.target.value : value) }))} /></label><Button variant="ghost" size="icon" aria-label={t('Delete concern', 'Eliminar inquietud')} disabled={busy} onClick={() => run(async () => { const concerns = profile.concerns.filter((_, i) => i !== index); await updateProfile({ concerns }); setIncludedConcerns([]); setDraftEn(''); setDraftPatient(''); })}><X size={18} /></Button></div>)}{profile.concerns.length > 0 && <Button variant="secondary" disabled={busy} onClick={() => run(async () => { await updateProfile({ concerns: profile.concerns.filter(item => item.trim()) }); setIncludedConcerns([]); setDraftEn(''); setDraftPatient(''); setToast(t('Concern log saved.', 'Inquietudes guardadas.')); })}>{t('Save concerns', 'Guardar inquietudes')}</Button>}</section><Button variant="secondary" disabled={busy} onClick={() => run(async () => { setProfile(await api.resetProfile(profile.profile_id)); setIncludedConcerns([]); setDraftEn(''); setDraftPatient(''); setExplanation(null); setBarrier(null); setConcernSaved(false); setToast('Profile reset.'); })}><RotateCcw size={16} />{t('Reset my learning profile', 'Reiniciar mi perfil')}</Button></>}

        {screen === 'evaluation' && <><PageHeading title={t('Show the work.', 'Mostrar el trabajo.')} subtitle={t('Saved results, clear denominators, and honest limits.', 'Resultados guardados, denominadores claros y límites honestos.')} /><section className="panel"><div className="panel-heading"><h3>{t('Backend evaluation', 'Evaluación del backend')}</h3><Button variant="secondary" disabled={busy} onClick={() => run(async () => { setEvaluation(await api.evaluation()); })}><RotateCcw size={16} />{t('Load saved results', 'Cargar resultados')}</Button></div><Notice>{t('A synthetic-task benchmark is not clinical validation. Simulations must be labeled as simulations. Frontend rule checks are separate from the held-out ML benchmark.', 'Una prueba sintética no es validación clínica. Las simulaciones deben identificarse. Las pruebas de reglas del frontend son distintas de las pruebas de ML.')}</Notice>{!evaluation || evaluation.status === 'not_run' ? <EmptyState title={t('No evaluation results loaded.', 'No se cargaron resultados.')}>{t('Connect the backend and load /api/eval to inspect saved counts, per-label metrics, error examples, and the bandit simulation. No scores are invented here.', 'Conecta el backend y carga /api/eval para ver los conteos, métricas, errores y la simulación. No se inventan puntuaciones.')}</EmptyState> : <div className="evaluation-results"><h3>{t('Saved evaluation response', 'Respuesta de evaluación guardada')}</h3><p className="helper">{t('The complete saved response is shown to preserve its counts and denominators. Any simulation data is separate from observed results.', 'Se muestra la respuesta completa para conservar los conteos y denominadores. Los datos simulados son distintos de los observados.')}</p><pre>{JSON.stringify(evaluation, null, 2)}</pre></div>}</section><div className="two-column"><section className="panel"><h3>{t('What the frontend does', 'Qué hace el frontend')}</h3><ul className="plain-list"><li>{t('Checks source quotes against the supplied documents.', 'Comprueba las citas con los documentos.')}</li><li>{t('Keeps conflicting instructions unresolved.', 'Conserva los conflictos sin resolver.')}</li><li>{t('Uses narrow, labeled rules in seeded mode.', 'Usa reglas limitadas e identificadas en modo demo.')}</li><li>{t('Keeps every message editable and copy-only.', 'Permite editar y copiar cada mensaje.')}</li></ul></section><section className="panel"><h3>{t('What needs the backend', 'Qué requiere el backend')}</h3><ul className="plain-list"><li>{t('Open-ended extraction and explanations.', 'Extracción y explicaciones abiertas.')}</li><li>{t('ML classification and confirmed-label training.', 'Clasificación ML y entrenamiento con etiquetas confirmadas.')}</li><li>{t('Deepgram transcription and photo OCR.', 'Transcripción Deepgram y OCR de fotos.')}</li><li>{t('Saved held-out metrics and simulation outputs.', 'Métricas de prueba y simulaciones guardadas.')}</li></ul></section></div></>}
        </>}
        <footer className="page-footer"><span className="footer-brand"><Plus size={14} />rexo.</span><p>{t('A little clarity. A little confidence. A voice in your care.', 'Claridad. Confianza. Una voz en tu cuidado.')}</p><span>{t('Built for the person, after the visit.', 'Para la persona, después de la visita.')}</span></footer>
      </main>
    </div>
    {toast && <div className="toast" role="status"><Check size={18} />{toast}<button aria-label="Dismiss notification" onClick={() => setToast('')}><X size={15} /></button></div>}
    {resetOpen && <div className="modal-backdrop"><section ref={resetRef} className="reset-dialog" role="alertdialog" aria-modal="true" aria-labelledby="reset-title"><span className="small-icon peach"><RotateCcw size={22} /></span><h2 id="reset-title">{t('Start fresh?', '¿Empezar de nuevo?')}</h2><p>{t('This clears the demo cases, preferences, concern log, and message drafts for this demo session.', 'Esto borra casos, preferencias, inquietudes y borradores de esta sesión.')}</p><div className="form-actions"><Button variant="secondary" autoFocus disabled={busy} onClick={() => setResetOpen(false)}>{t('Keep my session', 'Mantener mi sesión')}</Button><Button disabled={busy} onClick={() => run(async () => { await api.reset(); setPlan(null); setProfile(await api.createProfile({ language: profile.language })); setCases(await api.demoCases()); setUrgent(false); setScreen('home'); setAvs(''); setNote(''); setSyntheticConfirmed(false); setConcern(''); setBarrier(null); setConcernSaved(false); setExplanation(null); setTeachback(null); setAnswer(null); setResponse(''); setQuestion(''); setDraftEn(''); setDraftPatient(''); setEvaluation(null); setResetOpen(false); setToast(t('A fresh start. Your demo has been reset.', 'La demo se ha reiniciado.')); })}>{t('Reset demo', 'Reiniciar demo')}<ArrowRight size={16} /></Button></div></section></div>}
  </div>;
}

function PageHeading({ step, title, subtitle }: { step?: string; title: string; subtitle: string }) {
  return <div className="page-heading">{step && <div className="step-kicker"><span>{step}</span><span className="step-line" /></div>}<h1>{title}</h1><p>{subtitle}</p></div>;
}
